Partially resolves https://github.com/laravel/framework/issues/44214.

Repeatedly running following script (which happens during PHPUnit test setup) slowly but steadily leaks memory since the `register_shutdown_function` is never released:

```php
<?php

namespace Tests\Feature;

require_once __DIR__. '/../../vendor/autoload.php';

use App\Exceptions\Handler;
use Illuminate\Contracts\Console\Kernel;
use Illuminate\Contracts\Debug\ExceptionHandler;
use Illuminate\Foundation\Application;

function createApplication()
{

    $app = new Application(
        $_ENV['APP_BASE_PATH'] ?? dirname(dirname(__DIR__))
    );

    $app->singleton(
        \Illuminate\Contracts\Http\Kernel::class,
        \App\Http\Kernel::class
    );

    $app->singleton(
        Kernel::class,
        \App\Console\Kernel::class
    );

    $app->singleton(
        ExceptionHandler::class,
        Handler::class
    );

    $app->make(Kernel::class)->bootstrap();

    return $app;
}

for ($i = 1; $i < 10000; ++$i) {
    createApplication()->flush();
    Artisan::forgetBootstrappers();
    Queue::createPayloadUsing(null);
    HandleExceptions::forgetApp();
    gc_collect_cycles();

    dump('Using ' . ((int) (memory_get_usage(true) / (1024 * 1024))) . 'MB in ' . $i . ' iterations.');
}
```

## SWEA 1953 탈주범 검거
- 구현
- https://swexpertacademy.com/main/code/problem/problemDetail.do?contestProbId=AV5PpLlKAQ4DFAUq&categoryId=AV5PpLlKAQ4DFAUq&categoryType=CODE&problemTitle=%ED%83%88%EC%A3%BC&orderBy=FIRST_REG_DATETIME



## 풀이

풀이 방식 소개

파이프 간의 이동을 bfs를 이용해 구현했습니다. Queue가 비어있지 않거나 시간 L안이라면 while문을 반복하며 파이프를 탐색합니다.  while문 안에 Queue의 크기만큼 for문을 돌며 시간 L을 체크해 주었습니다.

~~~java
while (!q.isEmpty() && l > 0) {
	int sz = q.size();
	//1시간에 이동 가능한 거리
	for (int s = 0; s < sz; ++s) {
		Point now = q.poll();
		answer++;
		//파이프별 이동가능한 위치 
		for (int i = 0; i < move[map[now.y][now.x]].length; ++i) {
			int dir = move[map[now.y][now.x]][i];
			int nx = now.x + dx[dir];
			int ny = now.y + dy[dir];
                        if (nx < 0 || nx >= M || ny < 0 || ny >= N)
                        continue;

			visit[ny][nx] = visit[now.y][now.x] + 1;
			q.offer(new Point(nx, ny));
		}
	}			
	l--;
}
~~~

파이프의 이동 반경을 체크해주기 위해서 2차원 배열 move를 만들었습니다 move를 통해 파이프마다 이동 가능한 방향을 정해주었습니다.

~~~java
static int[][] move = { { 0, }, { 0, 1, 2, 3 }, { 0, 2 }, { 1, 3 }, { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 0 } };
static int[] dx = { 0, 1, 0, -1 };
static int[] dy = { -1, 0, 1, 0 };

for (int i = 0; i < move[map[now.y][now.x]].length; ++i) {
	int dir = move[map[now.y][now.x]][i];
	int nx = now.x + dx[dir];
	int ny = now.y + dy[dir];
}
~~~


범인이 이동하기 위해선 파이프에서 파이프로만 이동이 가능하며 두 파이프가 연결되어 있어야 합니다.  HashSet move2를 만들어 기존 파이프의 방향 +2 =  움직일 파이프의 방향인지 체크해주었습니다. 

~~~java

//이동할 위치 파이프 체크
if (map[ny][nx] == 0)
continue;
//중복 체크
if (visit[ny][nx] != 0)
continue;
//이동할 파이프와 이어져 있는지 체크
Boolean nextDir = move2[map[ny][nx]].contains((dir + 2) % 4);
if (!nextDir)
continue;

~~~
## 소스코드
~~~java
class SWEA_1953_탈주범검거 {
	static int answer;
	static int N;
	static int M;
	static int R;
	static int C;
	static int L;
	static int[][] map;
	static int[][] visit;
	static int[][] move = { { 0, }, { 0, 1, 2, 3 }, { 0, 2 }, { 1, 3 }, { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 0 } };
	static int[] dx = { 0, 1, 0, -1 };
	static int[] dy = { -1, 0, 1, 0 };
	static Set<Integer>[] move2;

	public static void main(String args[]) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int T;
		T = Integer.parseInt(br.readLine());
		for (int test_case = 1; test_case <= T; test_case++) {
			// 입력
			StringTokenizer st = new StringTokenizer(br.readLine());
			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());
			R = Integer.parseInt(st.nextToken());
			C = Integer.parseInt(st.nextToken());
			L = Integer.parseInt(st.nextToken());
			map = new int[N][M];
			visit = new int[N][M];
			move2 = new Set[8];
			//hashset으로 각 파이프별 이동가능한 위치 저장
			for (int i = 1; i < 8; ++i) {
				move2[i] = new HashSet<>();
				for (int j = 0; j < move[i].length; ++j) {
					move2[i].add(move[i][j]);
				}
			}

			for (int i = 0; i < N; ++i) {
				st = new StringTokenizer(br.readLine());
				for (int j = 0; j < M; ++j) {
					map[i][j] = Integer.parseInt(st.nextToken());
				}
			}

			// start
			func(R, C, L);
			// end

			// 출력
			System.out.printf("#%d %d\n", test_case, answer);
		}
	}

	private static void func(int r, int c, int l) {
		Queue<Point> q = new LinkedList<>();
		q.offer(new Point(c, r));
		visit[r][c] = 1;
		answer = 0;
		//bfs로 탐색
		while (!q.isEmpty() && l > 0) {
			int sz = q.size();
			//1시간에 이동 가능한 거리
			for (int s = 0; s < sz; ++s) {
				Point now = q.poll();
				answer++;
				//파이프별 이동가능한 위치 
				for (int i = 0; i < move[map[now.y][now.x]].length; ++i) {
					int dir = move[map[now.y][now.x]][i];
					int nx = now.x + dx[dir];
					int ny = now.y + dy[dir];
					//범위 체크
					if (nx < 0 || nx >= M || ny < 0 || ny >= N)
						continue;
					//이동할 위치 파이프 체크
					if (map[ny][nx] == 0)
						continue;
					//중복 체크
					if (visit[ny][nx] != 0)
						continue;
					//이동할 파이프와 이어져 있는지 체크
					Boolean nextDir = move2[map[ny][nx]].contains((dir + 2) % 4);
					if (!nextDir)
						continue;
					visit[ny][nx] = visit[now.y][now.x] + 1;
					q.offer(new Point(nx, ny));
				}
			}			
			l--;
		}

	}
}
~~~

